<script setup>
import { ref, onMounted } from 'vue'
import api from '@/api/client'
const tasks=ref([]), birthdays=ref([]), inactive=ref([]), customers=ref([])
const taskCustomer=ref(''), title=ref(''), type=ref('manual'), due=ref(''), notes=ref(''), busy=ref(false), error=ref('')
async function refresh(){try{const [t,s,c]=await Promise.all([api.get('/provider/crm/retention/tasks'),api.get('/provider/crm/retention/suggestions'),api.get('/provider/crm/customers',{params:{per_page:100}})]);tasks.value=t.data.tasks?.data||[];birthdays.value=s.data.birthdays||[];inactive.value=s.data.inactive_customers||[];customers.value=c.data.customers?.data||[]}catch(e){error.value=e.response?.data?.message||'Unable to load retention dashboard.'}}
function quickTask(c,t,txt){taskCustomer.value=String(c.id);type.value=t;title.value=txt;due.value='';notes.value=''}
async function save(){if(!taskCustomer.value||!title.value.trim())return;busy.value=true;try{await api.post('/provider/crm/retention/tasks',{customer_id:Number(taskCustomer.value),type:type.value,title:title.value,notes:notes.value||null,due_at:due.value||null});title.value='';notes.value='';taskCustomer.value='';await refresh()}catch(e){error.value=e.response?.data?.message||'Failed to create reminder.'}finally{busy.value=false}}
async function done(id){try{await api.patch('/provider/crm/retention/tasks/'+id,{status:'completed'});await refresh()}catch(e){error.value=e.response?.data?.message||'Failed to update reminder.'}}
onMounted(refresh)
</script>
<template><div class="space-y-4"><p v-if="error" class="rounded-lg bg-red-50 p-3 text-sm text-red-700">{{error}}</p><div class="grid gap-4 lg:grid-cols-2"><section class="rounded-2xl border bg-white p-5"><h2 class="text-lg font-semibold">Follow-up reminders</h2><p v-if="!tasks.length" class="py-4 text-sm text-ink-soft">No open reminders yet.</p><ul class="divide-y"><li v-for="t in tasks" :key="t.id" class="flex items-start justify-between gap-2 py-3"><div><p class="font-medium">{{t.title}}</p><p class="text-sm text-ink-soft">{{t.customer?.name}} · {{t.due_at?new Date(t.due_at).toLocaleDateString():'No due date'}}</p><p v-if="t.notes" class="text-xs">{{t.notes}}</p></div><button @click="done(t.id)" class="rounded-lg border px-2 py-1 text-xs">Complete</button></li></ul></section><section class="rounded-2xl border bg-white p-5"><h2 class="text-lg font-semibold">Birthdays in the next 30 days</h2><p v-if="!birthdays.length" class="py-3 text-sm text-ink-soft">No upcoming birthdays saved.</p><ul class="divide-y"><li v-for="b in birthdays" :key="b.id" class="flex justify-between gap-2 py-2"><div><p class="font-medium">{{b.name}}</p><p class="text-xs text-ink-soft">{{b.next_birthday}}</p></div><button @click="quickTask(b,'birthday','Birthday greeting/offer: '+b.name)" class="rounded-lg border px-2 py-1 text-xs">Create task</button></li></ul><h3 class="mt-4 font-semibold">Win-back opportunities</h3><p class="text-sm text-ink-soft">{{inactive.length}} clients with no completed appointment in 90 days</p><ul class="divide-y"><li v-for="c in inactive.slice(0,6)" :key="c.id" class="flex justify-between gap-2 py-2"><span>{{c.name}}</span><button @click="quickTask(c,'win_back','Reconnect with '+c.name)" class="rounded-lg border px-2 py-1 text-xs">Follow-up</button></li></ul></section></div><section class="rounded-2xl border bg-white p-5"><h2 class="font-semibold">Add a follow-up reminder</h2><div class="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><select v-model="taskCustomer" class="rounded-lg border p-2"><option value="">Select customer</option><option v-for="c in customers" :key="c.id" :value="String(c.id)">{{c.name}}</option></select><input v-model="title" placeholder="Reminder title" class="rounded-lg border p-2"/><select v-model="type" class="rounded-lg border p-2"><option value="manual">General</option><option value="birthday">Birthday</option><option value="after_visit">After visit</option><option value="win_back">Win-back</option></select><input v-model="due" type="date" class="rounded-lg border p-2"/><button @click="save" :disabled="busy" class="rounded-lg bg-ink p-2 text-white">{{busy?'Saving…':'Save reminder'}}</button></div><textarea v-model="notes" placeholder="Notes (optional)" class="mt-3 w-full rounded-lg border p-2" rows="2"/></section></div></template>